// Command codegen generates the typed layer of the Didit Go SDK from
// openapi/ (docs/DESIGN.md section 5).
//
//	go run ./codegen          write the generated files
//	go run ./codegen -check   fail when the committed files are stale
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func main() {
	check := flag.Bool("check", false, "report stale generated files instead of writing them")
	dir := flag.String("dir", ".", "repository root")
	flag.Parse()
	if err := run(*dir, *check); err != nil {
		fmt.Fprintln(os.Stderr, "codegen:", err)
		os.Exit(1)
	}
}

// generatedMarker starts every generated file.
var generatedMarker = []byte("// Code generated by codegen from openapi/*.json. DO NOT EDIT.")

func run(dir string, check bool) error {
	files, err := Generate(dir)
	if err != nil {
		return err
	}
	want := map[string][]byte{}
	for _, f := range files {
		want[f.Name] = f.Content
	}
	// Existing generated files in the repository root.
	existing := map[string]bool{}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			return err
		}
		if bytes.HasPrefix(data, generatedMarker) {
			existing[e.Name()] = true
		}
	}
	var stale []string
	for name, content := range want {
		old, err := os.ReadFile(filepath.Join(dir, name))
		if err == nil && bytes.Equal(old, content) {
			continue
		}
		stale = append(stale, name)
		if !check {
			if err := os.WriteFile(filepath.Join(dir, name), content, 0o644); err != nil {
				return err
			}
		}
	}
	for name := range existing {
		if _, ok := want[name]; ok {
			continue
		}
		stale = append(stale, name+" (obsolete)")
		if !check {
			if err := os.Remove(filepath.Join(dir, name)); err != nil {
				return err
			}
		}
	}
	sort.Strings(stale)
	if check {
		if len(stale) > 0 {
			return fmt.Errorf("generated code is stale; run `go run ./codegen` and commit the result:\n  %s", strings.Join(stale, "\n  "))
		}
		fmt.Printf("Generated code is up to date (%d files).\n", len(want))
		return nil
	}
	fmt.Printf("Wrote %d files (%d changed).\n", len(want), len(stale))
	return nil
}

// Generate returns every generated file.
func Generate(dir string) ([]File, error) {
	spec, err := LoadSpec(dir)
	if err != nil {
		return nil, err
	}
	g := newGen(spec)
	g.markUsage()
	root, err := g.buildServices()
	if err != nil {
		return nil, err
	}
	return g.emit(root)
}
